<?php

declare(strict_types=1);

namespace CodeClubLuxembourg\Sb3Toolkit\Builder\Blocks;

use CodeClubLuxembourg\Sb3Toolkit\Builder\Block;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Field\SoundEffect;
use CodeClubLuxembourg\Sb3Toolkit\Builder\Input;

/**
 * Typed factories for Scratch "Sound" blocks.
 *
 * Generated by bin/generate-blocks.php — do not edit by hand.
 */
final class Sound
{
    public static function playUntilDone(string|Block $soundMenu): Block
    {
        return Block::make('sound_playuntildone')
            ->input('SOUND_MENU', Input::menu('sound_sounds_menu', 'SOUND_MENU', $soundMenu));
    }

    public static function play(string|Block $soundMenu): Block
    {
        return Block::make('sound_play')
            ->input('SOUND_MENU', Input::menu('sound_sounds_menu', 'SOUND_MENU', $soundMenu));
    }

    public static function stopAllSounds(): Block
    {
        return Block::make('sound_stopallsounds');
    }

    public static function changeEffectBy(int|float|Block|Input $value, SoundEffect $effect): Block
    {
        return Block::make('sound_changeeffectby')
            ->input('VALUE', $value)
            ->field('EFFECT', $effect->value);
    }

    public static function setEffectTo(int|float|Block|Input $value, SoundEffect $effect): Block
    {
        return Block::make('sound_seteffectto')
            ->input('VALUE', $value)
            ->field('EFFECT', $effect->value);
    }

    public static function clearEffects(): Block
    {
        return Block::make('sound_cleareffects');
    }

    public static function changeVolumeBy(int|float|Block|Input $volume): Block
    {
        return Block::make('sound_changevolumeby')
            ->input('VOLUME', $volume);
    }

    public static function setVolumeTo(int|float|Block|Input $volume): Block
    {
        return Block::make('sound_setvolumeto')
            ->input('VOLUME', $volume);
    }

    public static function volume(): Block
    {
        return Block::make('sound_volume');
    }
}
